#!/data/data/com.termux/files/usr/bin/bash
# HAYU - Ikon gambar untuk aset SVGA (gift, frame, car, dll)
# Developer bisa pilih ikon saat upload, atau tambah/ganti ikon aset lama lewat tombol 🖼 di SVGA Manager.
# Ikon tampil di tombol Gift (menggantikan emoji 🎁) dan di Toko.
# Jalankan di root repo:  bash pasang-ikon-gift.sh
set -e
cd "${REPO:-$PWD}"
D="app/src/main/java/com/hayu/app"
[ -f "$D/SvgaManagerActivity.kt" ] || { echo "❌ Jalankan di root repo Hayu-android"; exit 1; }
T="$(mktemp -d)"
cat > "$T/b.b64" <<'B64_EOF'

B64_EOF
base64 -d "$T/b.b64" > "$T/b.tgz"
mkdir "$T/new" && tar xzf "$T/b.tgz" -C "$T/new"
BK="$HOME/.hayu-backup-ikon-$(date +%H%M%S)"
N=0
for f in $(cd "$T/new" && find . -type f | sed 's#^\./##'); do
  [ -f "$f" ] && { mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; }
  mkdir -p "$(dirname "$f")"
  cp "$T/new/$f" "$f"
  echo "  dipasang $f"
  N=$((N+1))
done
rm -rf "$T"
echo "✅ $N file dipasang. Backup: $BK"
echo "Lanjut: git add -A && git commit -m 'ikon gambar untuk gift svga' && git push"
